#include <algorithm>
#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common Polybench-style definitions (e.g., DATA_TYPE, N)
#include "defines.hpp"

// include benchmark-specific definitions (e.g., N for trisolv)
#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Array initialization, translated from the original C version.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x[i] = -999;
 *     b[i] = i;
 *     for (j = 0; j <= i; j++)
 *       L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
 *   }
 *
 * Note on layout:
 *   C uses row-major L[i][j].
 *   We map to Halide::Buffer<L>(j, i) as in the GEMM example:
 *     - first dimension: column index j (fast varying)
 *     - second dimension: row index i (slow varying)
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> L,
                       Halide::Buffer<num_t, 1> x,
                       Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");

    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    Expr n_expr = Expr(n);

    // x[i] = -999
    init_x(i) = cast<num_t>(-999);

    // b[i] = i
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i + n - j + 1) * 2 / n  for j <= i
    // We store L(j, i) == L[i][j], and set unused upper-triangular entries to 0.
    init_L(j, i) = select(
        j <= i,
        cast<num_t>(((i + n_expr - j + 1) * 2) / n_expr),
        cast<num_t>(0));

    // Realize into the provided Buffers.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char* argv[]) {
    // Problem size (from trisolv.hpp / Polybench)
    int n = N;

    // Buffers:
    // L: lower-triangular matrix, stored as L(j, i) == L[i][j]
    // x: solution vector
    // b: right-hand side vector
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // Initialize arrays
    init_array(n, L, x, b);

    // Halide parameters for the kernel
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");
    Param<int> i_param("i_param");  // current forward-substitution index i

    L_param.set(L);
    x_param.set(x);  // initial state (will be overridden inside the loop)
    b_param.set(b);

    // We implement the forward substitution using a host-side loop over i.
    //
    // At iteration i, we compute:
    //
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // Using Halide, we represent a *single* iteration i as a pure Func "step"
    // that takes the current state x_in and produces a new state x_out:
    //
    //   - For indices t != i:      x_out[t] = x_in[t]   (unchanged)
    //   - For index t == i:        x_out[i] = (b[i] - sum_{j=0..i-1} L[i][j]*x_in[j]) / L[i][i]
    //
    // By iterating this transform for i = 0..n-1 on the host, we reproduce
    // the sequential DP semantics without illegal self-references in Halide.

    Var idx("idx");
    RDom r(0, i_param, "r");  // j runs from 0 to i-1 at runtime

    // dot() = sum_{j=0..i-1} L[i][j] * x[j]
    // Remember: we store L(j, i) == original L[i][j].
    Func dot("dot");
    dot() = cast<num_t>(0);
    dot() += L_param(r, i_param) * x_param(r);

    // One step of forward substitution at index i_param
    Func step("step");
    step(idx) = select(
        idx == i_param,
        (b_param(i_param) - dot()) / L_param(i_param, i_param),
        x_param(idx));

    // Compile the Halide pipeline once (JIT)
    step.compile_jit();

    // Double buffers to hold the evolving solution x
    Halide::Buffer<num_t, 1> x_curr(n);
    Halide::Buffer<num_t, 1> x_next(n);

    // Initialize x_curr from the initial x (even though the algorithm
    // overwrites x[i] from b[i], this keeps semantics clear)
    x_curr.copy_from(x);

    // Time the forward substitution
    auto start = std::chrono::high_resolution_clock::now();

    // Host-driven loop over i: each iteration applies one Halide "step"
    for (int i = 0; i < n; i++) {
        i_param.set(i);
        x_param.set(x_curr);      // current state as input
        step.realize(x_next);     // compute next state
        std::swap(x_curr, x_next);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // x_curr now holds the final solution vector; copy into x for consistency
    x.copy_from(x_curr);

    // Optionally print the result (similar spirit to Polybench's print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    // Print the elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
