using num_t = DATA_TYPE;

using namespace Halide;

// Array initialization translated to Halide.
static
void init_array(int n,
                Halide::Buffer<num_t, 2> L,
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Func init_L("init_L"), init_x("init_x"), init_b("init_b");

    // x[i] = -999
    init_x(i) = cast<num_t>(-999);

    // b[i] = i
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i, otherwise 0
    // Mapping: C L[i][j] -> Halide L(j, i)
    init_L(j, i) = select(j <= i,
                          cast<num_t>((i + n - j + 1) * 2) / cast<int>(n),
                          cast<num_t>(0));

    // Realize into the provided Buffers.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   L: DATA_TYPE L[N][N]
    //   x: DATA_TYPE x[N]
    //   b: DATA_TYPE b[N]
    //
    // For L, we use (j, i) ordering: first dimension is column (j),
    // second dimension is row (i).
    Buffer<num_t, 2> L(n, n);
    Buffer<num_t, 1> x(n);
    Buffer<num_t, 1> b(n);

    // Initialize data
    init_array(n, L, x, b);

    // Halide parameters corresponding to the arrays and loop index i.
    ImageParam L_param(type_of<num_t>(), 2, "L_param");  // (j, i)
    ImageParam x_param(type_of<num_t>(), 1, "x_param");  // x[j]
    ImageParam b_param(type_of<num_t>(), 1, "b_param");  // b[i]
    Param<int> i_param("i");                             // current row i

    // Bind Buffers to ImageParams (the data can be updated in-place).
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // We construct a Halide pipeline that computes a single x[i]
    // given the current state of x[0..i-1], L, and b, following
    // the original C code exactly:
    //
    // x[i] = b[i];
    // for (j = 0; j < i; j++)
    //   x[i] -= L[i][j] * x[j];
    // x[i] = x[i] / L[i][i];
    //
    // We do this for a fixed i using a scalar Func x_i() and a reduction
    // over j, driven from C++ by a loop over i (forward substitution).

    Func x_i("x_i");
    RDom r(0, i_param, "r");  // j in [0, i_param)

    // Pure definition: x_i = b[i]
    x_i() = b_param(i_param);

    // Update definition: x_i -= L[i][j] * x[j]
    // Mapping: L[i][j] -> L_param(j, i_param)
    x_i() = x_i() - L_param(r, i_param) * x_param(r);

    // Final update: x_i /= L[i][i]
    x_i() = x_i() / L_param(i_param, i_param);

    // JIT-compile the pipeline once.
    x_i.compile_jit();

    using Clock = std::chrono::high_resolution_clock;

    auto start = Clock::now();

    // Run the forward substitution:
    // for (i = 0; i < n; i++) { ... }
    for (int i = 0; i < n; i++) {
        // Bind current i
        i_param.set(i);

        // Compute x[i] using the Halide pipeline.
        Buffer<num_t> x_scalar = x_i.realize();
        x(i) = x_scalar();
    }

    auto end = Clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination and for checking).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    // Print timing in seconds (like the GEMM example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
