// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays L, x, b.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x[i] = -999;
 *     b[i] = i;
 *     for (j = 0; j <= i; j++)
 *       L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
 *   }
 *
 * Mapping to Halide:
 *   C array L[i][j]  -> Buffer L(j, i)  (shape n x n)
 *   C array x[i]     -> Buffer x(i)
 *   C array b[i]     -> Buffer b(i)
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> L,
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");

    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // x[i] = -999;
    init_x(i) = cast<num_t>(-999);

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
    // Remember: L(i,j) in C -> L(j,i) in Halide.
    init_L(j, i) = cast<num_t>(((i + n - j + 1) * 2) / n);

    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   L[N][N], x[N], b[N]
    //
    // For L, we follow the convention: C L[i][j] -> Halide L(j, i)
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // Initialize data
    init_array(n, L, x, b);

    // ImageParams for Halide kernel
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Bind buffers to ImageParams (pointers remain valid across iterations)
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // Param for current row index i
    Param<int> i_param("i");

    // We compute:
    //   x[i] = (b[i] - sum_{j=0..i-1} L[i][j] * x[j]) / L[i][i]
    //
    // Using Halide, treating x as read-only input for each step and
    // updating x on the host between steps.

    // Reduction over j = 0 .. i-1
    RDom r(0, i_param, "r");

    Func dot_Lx("dot_Lx");
    // dot_Lx() = sum_{j=0..i-1} L[i][j] * x[j]
    // Remember: L[i][j] -> L_param(j, i_param)
    dot_Lx() = cast<num_t>(0);
    dot_Lx() += L_param(r, i_param) * x_param(r);

    Func x_i_func("x_i_func");
    // x_i = (b[i] - dot_Lx) / L[i][i]
    x_i_func() = (b_param(i_param) - dot_Lx()) / L_param(i_param, i_param);

    // Optional simple schedule: compute the reduction inside the scalar Func
    dot_Lx.compute_at(x_i_func, Var::outermost());
    x_i_func.compute_root();

    // JIT-compile the Halide kernel (once)
    x_i_func.compile_jit();

    // Time the forward substitution (main kernel)
    auto start = std::chrono::high_resolution_clock::now();

    // Host-driven forward substitution:
    // for (i = 0; i < n; i++) {
    //   x[i] = (b[i] - sum_{j=0..i-1} L[i][j] * x[j]) / L[i][i];
    // }
    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // Compute x[i] with Halide
        Realization r_x = x_i_func.realize();
        Buffer<num_t> x_scalar = r_x[0];
        num_t xi = x_scalar();

        // Update x on host for use in subsequent iterations
        x(i) = xi;
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (to stderr), similar to the gemm example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    // Print elapsed time in seconds (to stdout)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}

#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, DATA_PRINTF_MODIFIER, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (for trisolv)
#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays L, x, b to match the original C version.
 *
 * C code:
 *   for (i = 0; i < n; i++) {
 *     x[i] = -999;
 *     b[i] = i;
 *     for (j = 0; j <= i; j++)
 *       L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
 *   }
 *
 * Note: In C, L is declared as L[N][N] and accessed as L[i][j].
 * Following the convention in the GEMM example, we store L in a
 * Halide::Buffer with shape (n, n) but index it as L(j, i), i.e.
 * dimension 0 corresponds to column j and dimension 1 to row i.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> L,  // shape: (n_j, n_i) = (n, n)
                       Halide::Buffer<num_t, 1> x,  // shape: (n)
                       Halide::Buffer<num_t, 1> b)  // shape: (n)
{
    Var i("i"), j("j");

    Func init_L("init_L"), init_x("init_x"), init_b("init_b");

    // x[i] = -999;
    init_x(i) = cast<num_t>(-999);

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i
    // We implement this with a select on j <= i; entries with j > i
    // are set to 0 (they are never used by the algorithm).
    Expr ei = i;
    Expr ej = j;
    Expr n_expr = n;

    init_L(j, i) =
        select(ej <= ei,
               // Integer arithmetic followed by cast, as in C:
               // (i + n - j + 1) * 2 / n  -> integer division
               cast<num_t>(((ei + n_expr - ej + 1) * 2) / n_expr),
               cast<num_t>(0));

    // Realize into the provided Buffers.
    init_L.realize(L);
    init_x.realize(x);
    init_b.realize(b);
}

int main(int argc, char *argv[]) {
    // Problem size (PolyBench defines N in trisolv.hpp)
    int n = N;

    // Buffers:
    // L: lower-triangular matrix, C uses L[i][j], we store as L(j, i)
    Halide::Buffer<num_t, 2> L(n, n);
    // x: solution vector
    Halide::Buffer<num_t, 1> x(n);
    // b: right-hand side
    Halide::Buffer<num_t, 1> b(n);

    // Initialize arrays.
    init_array(n, L, x, b);

    // ------------------------------------------------------------------------
    // Halide description of one forward-substitution step.
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++) {
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //     x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    // }
    //
    // This has a loop-carried dependency on x: x[i] depends on x[0..i-1].
    // We express this using a host-driven loop over i, and for each i
    // we use Halide to compute:
    //
    //   x[i] = (b[i] - sum_{j=0..i-1} L[i][j]*x[j]) / L[i][i]
    //
    // As per the translation rules, we define a single-step Halide Func
    // that reads from ImageParams representing the current state of L, b, x,
    // and a Param<int> i_param indicating the row index.
    // ------------------------------------------------------------------------

    // ImageParams for inputs.
    ImageParam L_param(type_of<num_t>(), 2, "L_param");  // (j, i)
    ImageParam x_param(type_of<num_t>(), 1, "x_param");  // (i)
    ImageParam b_param(type_of<num_t>(), 1, "b_param");  // (i)

    // Scalar parameter for the current row i.
    Param<int> i_param("i_param");

    // Reduction domain over j = 0..i-1
    RDom r(0, i_param, "r");

    // dot() = sum_{j=0..i-1} L[i][j] * x[j]
    Func dot("dot");
    dot() = cast<num_t>(0);
    // C indexing: L[i][j] -> Halide: L_param(j, i_param)
    // C indexing: x[j]    -> Halide: x_param(j)
    dot() += L_param(r, i_param) * x_param(r);

    // compute_x() = (b[i] - dot()) / L[i][i]
    Func compute_x("compute_x");
    // C indexing: b[i] -> b_param(i_param)
    // C indexing: L[i][i] -> L_param(i_param, i_param)
    compute_x() = (b_param(i_param) - dot()) / L_param(i_param, i_param);

    // Bind the Buffers to the ImageParams once; we will mutate x in-place.
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // Compile the Halide pipeline ahead of time (JIT).
    compute_x.compile_jit();

    // ------------------------------------------------------------------------
    // Run the kernel and measure execution time (excluding JIT compilation).
    // ------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Host-driven forward substitution over i, using Halide to compute x[i].
    for (int i = 0; i < n; i++) {
        // Set the current row index.
        i_param.set(i);

        // Realize compute_x as a 0-D (scalar) Buffer.
        Halide::Buffer<num_t> x_i = compute_x.realize();

        // Extract the scalar value and write it back into x(i).
        x(i) = x_i();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print the resulting x vector (similar to print_array in C).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    // Print execution time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
